# Let's verify the hypothesis:
# - Connected components of size 1 keep 0
# - Connected components of size >= 2 become 8

input_grid = demo_data["pairs"][0]["input"]
output_grid = demo_data["pairs"][0]["output"]

def get_neighbors(pos, grid, size=13):
    r, c = pos
    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
        nr, nc = r+dr, c+dc
        if 0 <= nr < size and 0 <= nc < size and grid[nr][nc] == 0:
            yield (nr, nc)

def find_clusters_and_transform(grid, threshold=2):
    visited = set()
    result = [row[:] for row in grid]

    for r in range(13):
        for c in range(13):
            if grid[r][c] == 0 and (r,c) not in visited:
                cluster = set([(r,c)])
                stack = [(r,c)]
                while stack:
                    p = stack.pop()
                    for neighbor in get_neighbors(p, grid, 13):
                        if neighbor not in visited:
                            visited.add(neighbor)
                            cluster.add(neighbor)
                            stack.append(neighbor)

                # All cells in cluster of size >= threshold become 8
                if len(cluster) >= threshold:
                    for pos in cluster:
                        result[pos[0]][pos[1]] = 8

    return result

# Test with threshold=2
predicted = find_clusters_and_transform(input_grid, threshold=2)

# Check if prediction matches output
matches = True
for r in range(13):
    for c in range(13):
        if output_grid[r][c] != predicted[r][c]:
            print(f"Mismatch at ({r},{c}): expected {output_grid[r][c]}, got {predicted[r][c]}")
            matches = False

if matches:
    print("Hypothesis verified! The rule is:")
    print("- Find connected components of 0s")
    print("- Components of size >= 2: change all 0s to 8s")
    print("- Isolated 0s (size 1): keep as 0")
